import { httpRequestWith } from './transport/http-client.js';
import {
  initBehaviors,
  isBusy,
  resetBusy,
  setBusy,
} from './behaviors/index.js';

export const ENHANCED_ACTION_HEADER = 'X-Enhanced-Action';
export const ENHANCED_ACTION_ACCEPT = 'application/vnd.admin.enhanced+json';
export const ENHANCED_ACTION_HEADER_VALUE = '1';

export type EnhancedFragmentMode = 'replace';
export type EnhancedToastType = 'success' | 'error' | 'warning' | 'info' | string;

export interface EnhancedActionToast {
  type?: EnhancedToastType;
  message?: string;
}

export interface EnhancedActionFragment {
  selector?: string;
  mode?: EnhancedFragmentMode | string;
  html?: string;
}

export interface EnhancedActionError {
  message?: string;
  fields?: Record<string, string>;
}

export interface EnhancedActionEnvelope {
  version?: number;
  ok?: boolean;
  toast?: EnhancedActionToast;
  toasts?: EnhancedActionToast[];
  fragments?: EnhancedActionFragment[];
  focus?: string;
  redirect?: string;
  error?: EnhancedActionError;
}

export interface EnhancedActionRuntimeOptions {
  fetch?: typeof fetch;
  document?: Document;
  toast?: EnhancedToastSink;
  navigate?: (url: string) => void;
  requestHeader?: string;
  requestHeaderValue?: string;
  request_header?: string;
  request_header_value?: string;
  accept?: string;
  onFragmentsApplied?: (fragments: EnhancedActionFragment[]) => void | Promise<void>;
  liveDebounceMs?: number;
}

export interface EnhancedActionController {
  destroy(): void;
}

export interface EnhancedToastSink {
  success?: (message: string) => void;
  error?: (message: string) => void;
  warning?: (message: string) => void;
  info?: (message: string) => void;
  show?: (message: string, type?: string) => void;
}

type EnhancedResponseRead = {
  envelope: EnhancedActionEnvelope;
  enhanced: boolean;
  navigationURL?: string;
};

export function initEnhancedActions(
  root: Document | HTMLElement = document,
  options: EnhancedActionRuntimeOptions = {},
): EnhancedActionController {
  const doc = options.document ?? ownerDocument(root);
  const handleSubmit = (event: SubmitEvent) => {
    const form = formFromSubmitTarget(event.target, doc);
    if (!form || !form.matches('form[data-enhance-action]')) {
      return;
    }
    if (!canEnhance(options.fetch ?? globalThis.fetch, form.ownerDocument)) {
      return;
    }
    if (isLiveForm(form)) {
      event.preventDefault();
      cancelLiveTimer(form);
      void runLiveRequest(form, { ...options, document: doc });
      return;
    }
    if (isBusy(form)) {
      event.preventDefault();
      return;
    }
    event.preventDefault();
    void submitEnhancedForm(form, event.submitter, { ...options, document: doc });
  };
  const handleInput = (event: Event) => {
    const form = ownerFormOf(event.target);
    if (!form || !form.matches('form[data-enhance-action]') || !isLiveForm(form)) {
      return;
    }
    if (!canEnhance(options.fetch ?? globalThis.fetch, form.ownerDocument)) {
      return;
    }
    scheduleLiveRequest(form, event.target, { ...options, document: doc });
  };
  root.addEventListener('submit', handleSubmit as EventListener);
  root.addEventListener('input', handleInput);
  return {
    destroy() {
      root.removeEventListener('submit', handleSubmit as EventListener);
      root.removeEventListener('input', handleInput);
    },
  };
}

export async function submitEnhancedForm(
  form: HTMLFormElement,
  submitter: HTMLElement | null,
  options: EnhancedActionRuntimeOptions = {},
): Promise<EnhancedActionEnvelope | null> {
  const fetchImpl = options.fetch ?? globalThis.fetch;
  if (!canEnhance(fetchImpl, form.ownerDocument)) {
    return null;
  }
  const action = resolveFormAction(form, submitter);
  if (!action) {
    return null;
  }
  const method = resolveFormMethod(form, submitter);
  const FormDataCtor = formDataConstructor(form.ownerDocument);
  const HeadersCtor = headersConstructor(form.ownerDocument);
  const formData = new FormDataCtor(form);
  appendSubmitterValue(formData, submitter);
  const requestURL = resolveRequestURL(action, method, formData);
  clearEnhancedErrors(form);
  const headers = new HeadersCtor();
  headers.set(enhancedRequestHeader(options), enhancedRequestHeaderValue(options));
  headers.set('Accept', enhancedActionAccept(options));
  const busy = setBusy(form, {
    submitter,
    indicator: form.getAttribute('data-busy-indicator')?.trim() === 'submitter' ? 'submitter' : 'all',
  });
  try {
    const response = await httpRequestWith(fetchImpl, requestURL, {
      method,
      headers,
      body: method === 'GET' || method === 'HEAD' ? undefined : requestBody(form, submitter, formData),
      credentials: 'same-origin',
    });
    const result = await readEnhancedResponse(response, options);
    const envelope = result.envelope;
    if (result.navigationURL && response.ok) {
      navigateEnhancedFallback(result.navigationURL, options, form.ownerDocument);
      return envelope;
    }
    if (!response.ok || envelope.ok === false) {
      const doc = options.document ?? form.ownerDocument;
      await applyEnhancedFragments(envelope, options, doc);
      applyEnhancedErrors(form, envelope);
      showEnhancedToasts(envelope, options.toast);
      focusEnhancedTarget(envelope, doc);
      return envelope;
    }
    await applyEnhancedEnvelope(envelope, options);
    return envelope;
  } catch (error) {
    const message = error instanceof Error ? error.message : 'Request failed';
    const envelope: EnhancedActionEnvelope = {
      ok: false,
      error: { message },
      toasts: [{ type: 'error', message }],
    };
    applyEnhancedErrors(form, envelope);
    showEnhancedToasts(envelope, options.toast);
    return envelope;
  } finally {
    busy.reset();
  }
}

export async function applyEnhancedEnvelope(
  envelope: EnhancedActionEnvelope,
  options: EnhancedActionRuntimeOptions = {},
): Promise<void> {
  const doc = options.document ?? globalThis.document;
  await applyEnhancedFragments(envelope, options, doc);
  showEnhancedToasts(envelope, options.toast);
  focusEnhancedTarget(envelope, doc);
}

async function applyEnhancedFragments(
  envelope: EnhancedActionEnvelope,
  options: EnhancedActionRuntimeOptions,
  doc: Document,
): Promise<void> {
  const applied: EnhancedActionFragment[] = [];
  const appliedRoots: HTMLElement[] = [];
  for (const fragment of envelope.fragments ?? []) {
    const replacement = applyEnhancedFragmentRoot(doc, fragment);
    if (replacement) {
      applied.push(fragment);
      appliedRoots.push(replacement);
    }
  }
  if (applied.length > 0) {
    await reinitializeEnhancedFragments(options, appliedRoots);
    await options.onFragmentsApplied?.(applied);
    dispatchEnhancedFragmentsApplied(doc, applied, appliedRoots);
  }
}

export function applyEnhancedFragment(doc: Document, fragment: EnhancedActionFragment): boolean {
  return !!applyEnhancedFragmentRoot(doc, fragment);
}

function applyEnhancedFragmentRoot(doc: Document, fragment: EnhancedActionFragment): HTMLElement | null {
  const selector = String(fragment.selector ?? '').trim();
  const html = String(fragment.html ?? '').trim();
  const mode = String(fragment.mode ?? 'replace').trim() || 'replace';
  if (!selector || !html || mode !== 'replace') {
    return null;
  }
  const target = doc.querySelector(selector);
  if (!target) {
    return null;
  }
  const template = doc.createElement('template');
  template.innerHTML = html;
  const replacement = template.content.firstElementChild;
  if (!replacement) {
    return null;
  }
  target.replaceWith(replacement);
  return replacement as HTMLElement;
}

function canEnhance(fetchImpl?: typeof fetch, doc?: Document): fetchImpl is typeof fetch {
  return typeof fetchImpl === 'function' && !!formDataConstructor(doc) && !!headersConstructor(doc);
}

async function readEnhancedResponse(
  response: Response,
  options: EnhancedActionRuntimeOptions = {},
): Promise<EnhancedResponseRead> {
  const contentType = response.headers?.get('Content-Type') ?? '';
  const enhancedContentType = isEnhancedActionContentType(contentType, options);
  const plainJSONContentType = isPlainJSONContentType(contentType);
  if (!enhancedContentType && !plainJSONContentType) {
    const navigationURL = enhancedFallbackNavigationURL(response);
    if (response.ok && navigationURL) {
      return {
        enhanced: false,
        navigationURL,
        envelope: { ok: true, redirect: navigationURL },
      };
    }
    return {
      enhanced: false,
      envelope: {
        ok: false,
        error: {
          message: response.ok
            ? 'Expected an enhanced action response.'
            : `Request failed (${response.status})`,
        },
      },
    };
  }
  try {
    const payload = await response.json() as unknown;
    if (payload && typeof payload === 'object' && !Array.isArray(payload)) {
      if (enhancedContentType || isVersionedEnhancedActionEnvelopePayload(payload)) {
        return { enhanced: true, envelope: payload as EnhancedActionEnvelope };
      }
    }
  } catch {
    // Fall through to a generic envelope.
  }
  return {
    enhanced: enhancedContentType,
    envelope: {
      ok: false,
      error: {
        message: response.ok
          ? 'Expected an enhanced action response.'
          : `Request failed (${response.status})`,
      },
    },
  };
}

function isEnhancedActionContentType(
  contentType: string,
  options: EnhancedActionRuntimeOptions = {},
): boolean {
  const actual = mediaTypeOnly(contentType);
  if (!actual) {
    return false;
  }
  const configuredAccept = String(options.accept ?? '').trim();
  const expected = (configuredAccept || ENHANCED_ACTION_ACCEPT)
    .split(',')
    .map(mediaTypeOnly)
    .filter(Boolean);
  return expected.includes(actual);
}

function isPlainJSONContentType(contentType: string): boolean {
  const actual = mediaTypeOnly(contentType);
  return actual === 'application/json';
}

function mediaTypeOnly(contentType: string): string {
  return String(contentType ?? '').split(';', 1)[0].trim().toLowerCase();
}

function isVersionedEnhancedActionEnvelopePayload(payload: object): boolean {
  const record = payload as Record<string, unknown>;
  if (record.version !== 1) {
    return false;
  }
  return [
    'ok',
    'toast',
    'toasts',
    'fragments',
    'focus',
    'redirect',
    'error',
  ].some((key) => Object.prototype.hasOwnProperty.call(payload, key));
}

function enhancedFallbackNavigationURL(response: Response): string {
  const url = String(response.url ?? '').trim();
  if (!url || !response.redirected) {
    return '';
  }
  return url;
}

function navigateEnhancedFallback(url: string, options: EnhancedActionRuntimeOptions, doc: Document): void {
  if (typeof options.navigate === 'function') {
    options.navigate(url);
    return;
  }
  doc.defaultView?.location.assign(url);
}

function resolveFormAction(form: HTMLFormElement, submitter: HTMLElement | null): string {
  const submitterAction = submitter?.getAttribute('formaction')?.trim();
  return submitterAction || form.getAttribute('action')?.trim() || form.action || '';
}

function resolveFormMethod(form: HTMLFormElement, submitter: HTMLElement | null): string {
  const submitterMethod = submitter?.getAttribute('formmethod')?.trim();
  return (submitterMethod || form.getAttribute('method') || form.method || 'GET').trim().toUpperCase() || 'GET';
}

function formFromSubmitTarget(target: EventTarget | null, doc: Document): HTMLFormElement | null {
  const win = doc.defaultView;
  if (win?.HTMLFormElement && target instanceof win.HTMLFormElement) {
    return target;
  }
  if (typeof HTMLFormElement !== 'undefined' && target instanceof HTMLFormElement) {
    return target;
  }
  return null;
}

function formDataConstructor(doc?: Document): typeof FormData {
  const win = doc?.defaultView;
  return win?.FormData ?? globalThis.FormData;
}

function headersConstructor(doc?: Document): typeof Headers {
  const win = doc?.defaultView;
  return win?.Headers ?? globalThis.Headers;
}

function enhancedRequestHeader(options: EnhancedActionRuntimeOptions): string {
  return String(options.requestHeader || options.request_header || ENHANCED_ACTION_HEADER).trim() || ENHANCED_ACTION_HEADER;
}

function enhancedRequestHeaderValue(options: EnhancedActionRuntimeOptions): string {
  return String(options.requestHeaderValue || options.request_header_value || ENHANCED_ACTION_HEADER_VALUE).trim() || ENHANCED_ACTION_HEADER_VALUE;
}

function enhancedActionAccept(options: EnhancedActionRuntimeOptions): string {
  return String(options.accept || ENHANCED_ACTION_ACCEPT).trim() || ENHANCED_ACTION_ACCEPT;
}

function resolveRequestURL(action: string, method: string, body: FormData): string {
  if (method !== 'GET' && method !== 'HEAD') {
    return action;
  }
  const params = new URLSearchParams();
  body.forEach((value, name) => {
    params.append(name, typeof value === 'string' ? value : value.name);
  });
  const encoded = params.toString();
  if (!encoded) {
    return action;
  }
  try {
    const base = typeof location !== 'undefined' && location?.href ? location.href : undefined;
    const url = new URL(action, base);
    params.forEach((value, name) => {
      url.searchParams.append(name, value);
    });
    if (/^[a-zA-Z][a-zA-Z\d+\-.]*:/.test(action) || action.startsWith('//')) {
      return url.toString();
    }
    return `${url.pathname}${url.search}${url.hash}`;
  } catch {
    const hashIndex = action.indexOf('#');
    const prefix = hashIndex >= 0 ? action.slice(0, hashIndex) : action;
    const hash = hashIndex >= 0 ? action.slice(hashIndex) : '';
    const separator = prefix.includes('?') ? '&' : '?';
    return `${prefix}${separator}${encoded}${hash}`;
  }
}

function appendSubmitterValue(body: FormData, submitter: HTMLElement | null): void {
  if (!isSubmitterControl(submitter)) {
    return;
  }
  const name = submitter.getAttribute('name')?.trim();
  if (!name || body.has(name)) {
    return;
  }
  body.append(name, submitter.getAttribute('value') ?? '');
}

// Mirror the native form: multipart only when the form or submitter declares it.
function requestBody(form: HTMLFormElement, submitter: HTMLElement | null, formData: FormData): FormData | URLSearchParams {
  const submitterEnctype = isSubmitterControl(submitter) ? submitter.getAttribute('formenctype')?.trim() : '';
  const enctype = (submitterEnctype || form.getAttribute('enctype') || '').trim().toLowerCase();
  if (enctype === 'multipart/form-data') {
    return formData;
  }
  const params = new URLSearchParams();
  formData.forEach((value, name) => {
    params.append(name, typeof value === 'string' ? value : value.name);
  });
  return params;
}

function isSubmitterControl(submitter: HTMLElement | null): submitter is HTMLButtonElement | HTMLInputElement {
  if (!submitter) {
    return false;
  }
  const win = submitter.ownerDocument?.defaultView;
  if (win?.HTMLButtonElement && submitter instanceof win.HTMLButtonElement) {
    return true;
  }
  if (win?.HTMLInputElement && submitter instanceof win.HTMLInputElement) {
    return true;
  }
  if (typeof HTMLButtonElement !== 'undefined' && submitter instanceof HTMLButtonElement) {
    return true;
  }
  return typeof HTMLInputElement !== 'undefined' && submitter instanceof HTMLInputElement;
}

function showEnhancedToasts(envelope: EnhancedActionEnvelope, explicitToast?: EnhancedToastSink): void {
  const sink = explicitToast ?? getEnhancedWindow().toastManager;
  const toasts = [...(envelope.toasts ?? [])];
  if (envelope.toast) {
    toasts.unshift(envelope.toast);
  }
  for (const toast of toasts) {
    const message = String(toast.message ?? '').trim();
    if (!message) {
      continue;
    }
    const type = String(toast.type ?? 'info').trim() || 'info';
    const typed = sink?.[type as keyof EnhancedToastSink];
    if (typeof typed === 'function') {
      typed.call(sink, message);
    } else if (typeof sink?.show === 'function') {
      sink.show(message, type);
    }
  }
}

function focusEnhancedTarget(envelope: EnhancedActionEnvelope, doc: Document): void {
  const selector = String(envelope.focus ?? '').trim();
  if (!selector) {
    return;
  }
  const target = doc.querySelector<HTMLElement>(selector);
  target?.focus?.();
}

function clearEnhancedErrors(form: HTMLFormElement): void {
  for (const node of Array.from(form.querySelectorAll('[data-enhance-generated-error]'))) {
    node.remove();
  }
  for (const field of Array.from(form.querySelectorAll<HTMLElement>('[aria-invalid="true"]'))) {
    field.removeAttribute('aria-invalid');
  }
  const targetSelector = form.getAttribute('data-enhance-error-target')?.trim();
  const target = targetSelector ? form.ownerDocument.querySelector<HTMLElement>(targetSelector) : null;
  if (target) {
    target.textContent = '';
    target.setAttribute('hidden', '');
  }
}

function applyEnhancedErrors(form: HTMLFormElement, envelope: EnhancedActionEnvelope): void {
  const fields = envelope.error?.fields ?? {};
  for (const [field, message] of Object.entries(fields)) {
    const input = form.querySelector<HTMLElement>(`[name="${cssEscape(field)}"]`);
    if (!input) {
      continue;
    }
    input.setAttribute('aria-invalid', 'true');
    const error = form.ownerDocument.createElement('div');
    error.setAttribute('data-enhance-generated-error', 'true');
    error.setAttribute('data-enhance-field-error-for', field);
    error.className = 'mt-1 text-xs text-rose-600';
    error.textContent = message;
    input.insertAdjacentElement('afterend', error);
  }
  const message = String(envelope.error?.message ?? '').trim();
  if (!message) {
    return;
  }
  const targetSelector = form.getAttribute('data-enhance-error-target')?.trim();
  const target = targetSelector ? form.ownerDocument.querySelector<HTMLElement>(targetSelector) : null;
  if (target) {
    target.textContent = message;
    target.removeAttribute('hidden');
  }
}

function cssEscape(value: string): string {
  const css = globalThis.CSS as ({ escape?: (value: string) => string } | undefined);
  if (typeof css?.escape === 'function') {
    return css.escape(value);
  }
  return value.replace(/["\\]/g, '\\$&');
}

async function reinitializeEnhancedFragments(options: EnhancedActionRuntimeOptions, roots: HTMLElement[]): Promise<void> {
  for (const root of roots) {
    initBehaviors(root, { window: root.ownerDocument.defaultView ?? undefined });
    resetBusy(root);
  }
  const rel = getEnhancedWindow().FormgenRelationships;
  if (typeof rel?.initRelationships === 'function') {
    await rel.initRelationships();
  }
}

function getEnhancedWindow(): {
  toastManager?: EnhancedToastSink;
  FormgenRelationships?: {
    initRelationships?: () => Promise<unknown> | unknown;
  };
} {
  return (globalThis.window ?? {}) as {
    toastManager?: EnhancedToastSink;
    FormgenRelationships?: {
      initRelationships?: () => Promise<unknown> | unknown;
    };
  };
}

function dispatchEnhancedFragmentsApplied(doc: Document, fragments: EnhancedActionFragment[], roots: HTMLElement[]): void {
  const event = new CustomEvent('go-admin:enhanced-fragments-applied', {
    bubbles: true,
    detail: { fragments, roots },
  });
  doc.dispatchEvent(event);
}

function ownerDocument(root: Document | HTMLElement): Document {
  return root instanceof Document ? root : root.ownerDocument;
}

const DEFAULT_LIVE_DEBOUNCE_MS = 180;

interface LiveFormState {
  timer?: ReturnType<typeof setTimeout>;
  controller?: AbortController;
  sequence: number;
  lastURL?: string;
}

const liveStates = new WeakMap<HTMLFormElement, LiveFormState>();

function isLiveForm(form: HTMLFormElement): boolean {
  return form.hasAttribute('data-enhance-live') && resolveFormMethod(form, null) === 'GET';
}

function liveState(form: HTMLFormElement): LiveFormState {
  let state = liveStates.get(form);
  if (!state) {
    state = { sequence: 0 };
    liveStates.set(form, state);
  }
  return state;
}

function cancelLiveTimer(form: HTMLFormElement): void {
  const state = liveStates.get(form);
  if (state?.timer !== undefined) {
    clearTimeout(state.timer);
    state.timer = undefined;
  }
}

function ownerFormOf(target: EventTarget | null): HTMLFormElement | null {
  const control = target as { form?: HTMLFormElement | null } | null;
  return control && control.form ? control.form : null;
}

function liveNumber(value: string | undefined, fallback: number): number {
  const parsed = Number.parseInt(String(value ?? ''), 10);
  return Number.isFinite(parsed) && parsed >= 0 ? parsed : fallback;
}

function scheduleLiveRequest(form: HTMLFormElement, trigger: EventTarget | null, options: EnhancedActionRuntimeOptions): void {
  const min = liveNumber(form.dataset.enhanceLiveMin, 1);
  const text = (trigger as { value?: unknown } | null)?.value;
  const typed = typeof text === 'string' && (trigger as HTMLInputElement).type !== 'radio' && (trigger as HTMLInputElement).type !== 'checkbox';
  if (typed) {
    const length = text.trim().length;
    if (length > 0 && length < min) {
      cancelLiveTimer(form);
      return;
    }
  }
  const state = liveState(form);
  cancelLiveTimer(form);
  const delay = liveNumber(form.dataset.enhanceLiveDebounce, options.liveDebounceMs ?? DEFAULT_LIVE_DEBOUNCE_MS);
  state.timer = setTimeout(() => {
    state.timer = undefined;
    void runLiveRequest(form, options);
  }, delay);
}

// Live forms keep the controls usable: they mark the form pending instead of busy,
// abort superseded requests and drop responses that arrive out of order.
async function runLiveRequest(form: HTMLFormElement, options: EnhancedActionRuntimeOptions): Promise<void> {
  const fetchImpl = options.fetch ?? globalThis.fetch;
  if (!canEnhance(fetchImpl, form.ownerDocument)) {
    return;
  }
  const action = resolveFormAction(form, null);
  if (!action) {
    return;
  }
  const FormDataCtor = formDataConstructor(form.ownerDocument);
  const HeadersCtor = headersConstructor(form.ownerDocument);
  const requestURL = resolveRequestURL(action, 'GET', new FormDataCtor(form));
  const state = liveState(form);
  if (requestURL === state.lastURL) {
    return;
  }
  state.controller?.abort();
  const AbortCtor = form.ownerDocument.defaultView?.AbortController ?? globalThis.AbortController;
  const controller = typeof AbortCtor === 'function' ? new AbortCtor() : undefined;
  state.controller = controller;
  state.lastURL = requestURL;
  const sequence = ++state.sequence;
  const doc = options.document ?? form.ownerDocument;
  const headers = new HeadersCtor();
  headers.set(enhancedRequestHeader(options), enhancedRequestHeaderValue(options));
  headers.set('Accept', enhancedActionAccept(options));
  form.setAttribute('aria-busy', 'true');
  form.dataset.enhanceLivePending = 'true';
  clearEnhancedErrors(form);
  try {
    const response = await httpRequestWith(fetchImpl, requestURL, {
      method: 'GET',
      headers,
      credentials: 'same-origin',
      signal: controller?.signal,
    });
    const result = await readEnhancedResponse(response, options);
    if (sequence !== state.sequence) {
      return;
    }
    const envelope = result.navigationURL
      ? { ok: false, error: { message: 'Expected an enhanced action response.' } }
      : result.envelope;
    if (!response.ok || envelope.ok === false) {
      state.lastURL = undefined;
      await applyEnhancedFragments(envelope, options, doc);
      applyEnhancedErrors(form, envelope);
      showEnhancedToasts(envelope, options.toast);
      return;
    }
    await applyEnhancedEnvelope(envelope, { ...options, document: doc });
  } catch (error) {
    if (sequence !== state.sequence || isAbortError(error)) {
      return;
    }
    state.lastURL = undefined;
    const message = error instanceof Error ? error.message : 'Request failed';
    applyEnhancedErrors(form, { ok: false, error: { message } });
  } finally {
    if (sequence === state.sequence) {
      form.removeAttribute('aria-busy');
      delete form.dataset.enhanceLivePending;
    }
  }
}

function isAbortError(error: unknown): boolean {
  return !!error && typeof error === 'object' && (error as { name?: string }).name === 'AbortError';
}
